INSERT INTO `pregunta` VALUES (1,'¿Que es una variable en programacion?','Una instruccion que siempre se repite','Un espacio identificado para almacenar un valor','Un error de compilacion','Un tipo de diagrama','B',1),(2,'¿Que estructura ejecuta instrucciones en un orden definido?','Secuencial','Selectiva','Repetitiva','Recursiva','A',1),(3,'¿Que palabra se usa normalmente para ingresar un dato en pseudocodigo?','ESCRIBIR','FIN','LEER','MIENTRAS','C',1),(4,'Si A = {1,2,3} y B = {2,3,4}, ¿cual es A interseccion B?','{1,4}','{2,3}','{1,2,3,4}','Conjunto vacio','B',2),(5,'¿Cual de las siguientes expresiones es una proposicion?','Abre la puerta','¿Que hora es?','5 es un numero primo','x + 2','C',2),(6,'En un grafo, ¿como se llama cada punto que representa un elemento?','Arista','Vertice','Camino','Peso','B',2),(7,'¿Que principio oculta el estado interno de un objeto?','Herencia','Polimorfismo','Encapsulamiento','Sobrecarga','C',3),(8,'¿Que permite crear una clase a partir de otra clase existente?','Abstraccion','Herencia','Composicion','Iteracion','B',3),(9,'¿Que es un objeto?','Una instancia de una clase','Unicamente un metodo','Un tipo de bucle','Una base de datos','A',3),(10,'¿Cual es la funcion principal de una clave primaria?','Duplicar filas','Identificar univocamente cada registro','Ordenar siempre de mayor a menor','Cifrar la tabla','B',4),(11,'¿Que clausula SQL combina filas relacionadas de dos tablas?','GROUP','DELETE','JOIN','ALTER','C',4),(12,'¿Que busca reducir la normalizacion de una base de datos?','La seguridad','La redundancia y las anomalías','El numero de usuarios','La longitud de las consultas','B',4),(13,'¿Que protocolo se utiliza para transferir paginas y recursos web?','FTP solamente','HTTP/HTTPS','SMTP','SSH','B',5),(14,'¿Para que se utiliza CSS?','Para estructurar tablas SQL','Para compilar Java','Para definir la presentacion visual de una pagina','Para administrar servidores','C',5),(15,'¿Que representa el DOM en una pagina web?','La estructura de objetos del documento','Un motor de base de datos','Un lenguaje de estilos','Un servidor DNS','A',5),(16,'¿Que describe un requisito funcional?','El color favorito del equipo','Una funcion que el sistema debe realizar','El precio del hardware','La marca del servidor','B',6),(17,'¿Cual es el objetivo principal de una prueba de software?','Agregar mas lineas de codigo','Encontrar defectos y verificar el comportamiento','Evitar documentar','Reemplazar los requisitos','B',6),(18,'¿Para que sirve un sistema de control de versiones como Git?','Para editar imagenes','Para registrar y coordinar cambios en el codigo','Para ejecutar consultas SQL','Para disenar redes fisicas','B',6),(19,'¿Cuánto vale x si 3x + 5 = 20?','3','5','7','10','B',7),(20,'¿Cuál es el resultado de 1/2 + 1/4?','1/4','1/2','3/4','1','C',7),(21,'¿Cuánto es 2 elevado a la cuarta potencia?','8','12','14','16','D',7),(22,'Si f(x) = 2x + 3, ¿cuánto vale f(4)?','8','11','12','14','B',7),(23,'¿Cuánto es el 20% de 150?','20','25','30','35','C',7),(24,'¿Cuál es el área de un rectángulo de 8 cm de largo y 3 cm de ancho?','11 cm²','22 cm²','24 cm²','48 cm²','C',7),(25,'¿Cuál es la raíz cuadrada principal de 81?','7','8','9','10','C',7),(26,'En la función y = 3x + 2, ¿cuál es la pendiente?','2','3','5','1','B',7),(34,'¿Qué es una variable en programación?','Un dato que nunca cambia','Un espacio con nombre para guardar valores','Una condición obligatoria','Un error de compilación','B',8),(35,'¿Qué estructura permite tomar decisiones según una condición?','SI ... ENTONCES','PARA','MIENTRAS','ESCRIBIR','A',8),(36,'¿Qué tipo de dato representa VERDADERO o FALSO?','Entero','Real','Booleano','Texto','C',8),(37,'¿Cuál es el resultado de 10 MOD 3?','0','1','3','10','B',8),(38,'¿Qué estructura repite instrucciones mientras se cumple una condición?','SI','SEGÚN','MIENTRAS','LEER','C',8),(39,'En un arreglo de 5 elementos cuyos índices comienzan en 0, ¿cuál es el último índice válido?','5','6','1','4','D',8),(40,'¿Cuál es 